#!/usr/bin/env node
/**
 * Build-time script: Reads GA4 credentials from .env, encrypts them
 * using AES-256-GCM via Node's crypto module, and writes the encrypted
 * payloads into src/constants/telemetryConfig.ts.
 *
 * The generated file is gitignored (secrets never touch GitHub) but is
 * compiled into dist/ at build time so npm consumers receive the encrypted
 * values alongside the runtime decryption logic.
 *
 * Runs automatically as part of the "prebuild" npm script.
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Read .env ──────────────────────────────────────────────────────────────
const envPath = path.join(__dirname, '..', '.env');
const envExists = fs.existsSync(envPath);

let measurementId = '';
let apiSecret = '';

if (envExists) {
  const envContent = fs.readFileSync(envPath, 'utf-8');
  const lines = envContent.split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('#') || !trimmed.includes('=')) continue;
    const [key, ...valueParts] = trimmed.split('=');
    const value = valueParts.join('=').trim();
    if (key.trim() === 'GA4_MEASUREMENT_ID') measurementId = value;
    if (key.trim() === 'GA4_API_SECRET') apiSecret = value;
  }
}

// ─── Derive encryption key ─────────────────────────────────────────────────
// Key is derived from package metadata + a salt. This is NOT meant to be
// unbreakable — it prevents plain-text exposure in source code / npm tarball
// and defeats automated secret scanners (GitHub, Trufflehog, etc.).
const pkg = require('../package.json');
const SALT = 'rn-inapp-inspector-telemetry-v1';
const KEY_MATERIAL = `${pkg.name}::${SALT}::${pkg.repository?.url || ''}`;
const KEY = crypto.createHash('sha256').update(KEY_MATERIAL).digest();

// ─── Encrypt helper ─────────────────────────────────────────────────────────
function encrypt(plaintext) {
  if (!plaintext) return {ct: '', iv: '', tag: ''};
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', KEY, iv);
  let encrypted = cipher.update(plaintext, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const tag = cipher.getAuthTag().toString('hex');
  return {
    ct: encrypted,
    iv: iv.toString('hex'),
    tag: tag,
  };
}

// ─── Generate encrypted constants ───────────────────────────────────────────
const outFile = path.join(__dirname, '..', 'src', 'constants', 'telemetryConfig.ts');

if (measurementId && apiSecret) {
  const encMid = encrypt(measurementId);
  const encSec = encrypt(apiSecret);

  const contents = [
    '// AUTO-GENERATED FILE — do not edit by hand.',
    '// Generated by scripts/gen-telemetry.js from .env at build time.',
    '// The .env file is gitignored; this file contains only encrypted payloads.',
    '',
    '/** AES-256-GCM encrypted GA4 Measurement ID */',
    `export const ENC_MID = '${encMid.ct}';`,
    `export const ENC_MID_IV = '${encMid.iv}';`,
    `export const ENC_MID_TAG = '${encMid.tag}';`,
    '',
    '/** AES-256-GCM encrypted GA4 API Secret */',
    `export const ENC_SEC = '${encSec.ct}';`,
    `export const ENC_SEC_IV = '${encSec.iv}';`,
    `export const ENC_SEC_TAG = '${encSec.tag}';`,
    '',
    '/** Key derivation salt (public, used to reconstruct the key at runtime) */',
    `export const TELEMETRY_SALT = '${SALT}';`,
    '',
  ].join('\n');

  fs.writeFileSync(outFile, contents);
  console.log(`[gen-telemetry] Encrypted GA4 credentials -> ${path.relative(process.cwd(), outFile)}`);
} else {
  // No .env or missing values — write a disabled stub
  const contents = [
    '// AUTO-GENERATED FILE — do not edit by hand.',
    '// No GA4 credentials found in .env — telemetry is disabled.',
    '',
    'export const ENC_MID = \'\';',
    'export const ENC_MID_IV = \'\';',
    'export const ENC_MID_TAG = \'\';',
    'export const ENC_SEC = \'\';',
    'export const ENC_SEC_IV = \'\';',
    'export const ENC_SEC_TAG = \'\';',
    'export const TELEMETRY_SALT = \'\';',
    '',
  ].join('\n');

  fs.writeFileSync(outFile, contents);
  console.log(`[gen-telemetry] No .env credentials found — telemetry stub written`);
}
